package az.achiqyol.config;
import org.springframework.context.annotation.*; import org.springframework.data.redis.cache.*; import org.springframework.data.redis.connection.RedisConnectionFactory; import java.time.Duration; @Configuration public class RedisConfig { @Bean RedisCacheManager cacheManager(RedisConnectionFactory factory) { return RedisCacheManager.builder(factory).cacheDefaults(RedisCacheConfiguration.defaultCacheConfig().entryTtl(Duration.ofMinutes(2))).transactionAware().build(); } }
